import serial

class MeterBus:
    def __init__(self, port, baudrate):
        self.port = serial.Serial(port, baudrate)
        self.port.timeout = 1

    def send_frame(self, frame):
        self.port.write(frame)

    def send_ping_frame(self, meterbus_port, address):
        frame = self._create_ping_frame(address)
        self.port.write(frame)

    def _create_ping_frame(self, address):
        # Create a ping frame with the given address
        # This is a simplified version, in a real implementation you would need to handle
        # more cases and errors
        if not isinstance(address, int):
            raise ValueError("Address must be an integer")
        if not 0x00 <= address <= 0xFF:
            raise ValueError("Invalid address")
        return bytes([0x10, 0x40, address, 0x40, 0x16])

